using AnimeJaNaiConfEditor.ViewModels;
using AnimeJaNai.Platform;
using ReactiveUI.Builder;
using System.Text.Json;
string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);
Environment.SetEnvironmentVariable("ANIMEJANAI_DATA_DIR",root);
Environment.SetEnvironmentVariable("ANIMEJANAI_ROOT",root);
Environment.SetEnvironmentVariable("ANIMEJANAI_INFERENCE_DIR",Path.Combine(root,"inference"));
RxAppBuilder.CreateReactiveUIBuilder().WithCoreServices().BuildApp();
string original="[global]\nbackend=DirectML\nrife_engine=fast\ndefault_slot=1\n[slot_1]\nprofile_name=Imported\nchain_1_pipeline_version=1\nchain_1_stage_count=2\nchain_1_stage_1_id=old-fruc\nchain_1_stage_1_kind=interpolate\nchain_1_stage_1_method=nvidia-fruc\nchain_1_stage_1_runtime=cuda\nchain_1_stage_1_enabled=no\nchain_1_stage_1_policy=fast\nchain_1_stage_1_factor_numerator=2\nchain_1_stage_1_sdk_library=/user/preserved-sdk\nchain_1_stage_1_future_option=keep\nchain_1_stage_2_id=quality\nchain_1_stage_2_kind=interpolate\nchain_1_stage_2_method=rife\nchain_1_stage_2_runtime=directml\nchain_1_stage_2_enabled=yes\nchain_1_stage_2_model=426\nchain_1_stage_2_policy=quality\nchain_1_stage_2_factor_numerator=4\n";
string active=Path.Combine(root,"animejanai.conf");File.WriteAllText(active,original);
MainWindowViewModel.Platform=MainWindowViewModel.Os.Windows;
var vm=new MainWindowViewModel();vm.HandleShowCustomProfile("1");
var checks=new List<string>();void Check(string name,bool ok){if(!ok)throw new Exception(name);checks.Add(name);}
Check("opening retired configuration does not write it",File.ReadAllText(active)==original);
string saved=Path.Combine(root,"saved.conf");vm.WriteAnimeJaNaiConf(saved);string text=File.ReadAllText(saved);
var round=vm.ReadAnimeJaNaiConf(saved);var stages=round.UpscaleSlots[0].Chains[0].Stages;
Check("disabled FRUC and unknown options survive save/reload",stages[0].Id=="old-fruc"&&!stages[0].Enabled&&stages[0].OptionsText.Contains("sdk_library=/user/preserved-sdk")&&stages[0].OptionsText.Contains("future_option=keep"));
Check("per-stage Quality has a portable legacy projection despite historical global Fast",text.Contains("chain_1_rife=yes")&&text.Contains("chain_1_rife_factor_numerator=4")&&stages[1].Policy=="quality"&&round.RifeEngine=="fast");
File.WriteAllText(Path.Combine(root,"summary.json"),JsonSerializer.Serialize(new{passed=true,checks,scope="New retired-provider and independent per-stage policy persistence; no GPU execution"},new JsonSerializerOptions{WriteIndented=true}));
Console.WriteLine(string.Join("\n",checks));
